<?php $fs=static fn(string$s):string=>ucfirst(str_replace('_',' ',$s));$mc=static fn(int$v):string=>'R$ '.number_format($v/100,2,',','.');?>
<header class="panel-page-heading"><div><span>Reserva #<?= (int)$reserva['id'] ?></span><h1><?= e($reserva['chacara_nome']) ?></h1><p><?= e($reserva['cliente_nome']) ?> &middot; <?= e($reserva['proprietario_nome']) ?></p></div><a class="btn btn-outline" href="<?= url('/admin/reservas') ?>">Voltar</a></header>
<section class="panel-card"><dl class="client-summary-list"><div><dt>Status</dt><dd><?= e($fs($reserva['status_reserva'])) ?></dd></div><div><dt>Pagamento</dt><dd><?= e($fs($reserva['status_pagamento'])) ?></dd></div><div><dt>Valor da reserva</dt><dd><?= e($mc((int)$reserva['valor_liquido_proprietario_centavos'])) ?></dd></div><div><dt>Taxa de opera&ccedil;&atilde;o PIX</dt><dd><?= e($mc((int)($reserva['taxa_operacao_pix_snapshot_centavos']??0))) ?></dd></div><div><dt>Total pago</dt><dd><?= e($mc((int)$reserva['valor_total_cliente_centavos'])) ?></dd></div><div><dt>Repasse</dt><dd><?= e($fs($reserva['repasse_status']??'legado')) ?></dd></div><div><dt>Reembolso</dt><dd><?= e($fs($reserva['reembolso_status']??'nenhum')) ?></dd></div><div><dt>Precifica&ccedil;&atilde;o</dt><dd><?= e($reserva['origem_precificacao']) ?> / vers&atilde;o <?= (int)$reserva['versao_precificacao'] ?></dd></div><?php if(!empty($reserva['divergencia_pagamento'])):?><div><dt>Aten&ccedil;&atilde;o</dt><dd>Pagamento com diverg&ecirc;ncia; requer concilia&ccedil;&atilde;o.</dd></div><?php endif;?></dl>
<form class="owner-property-form" method="post" action="<?= url('/admin/reservas/'.(int)$reserva['id'].'/transicao') ?>"><?= csrf_field() ?><label class="form-full">Motivo obrigat&oacute;rio<textarea name="motivo" maxlength="500" required></textarea></label><label class="form-full">Pol&iacute;tica financeira para cancelamento excepcional<textarea name="politica_financeira" maxlength="2000" placeholder="Obrigat&oacute;ria ao cancelar. Descreva o tratamento dos valores recebidos e repassados. O registro n&atilde;o executa estorno automaticamente."></textarea></label><div class="form-actions"><?php foreach(['cancelar'=>'Cancelar','aprovar_cancelamento'=>'Aprovar cancelamento','recusar_cancelamento'=>'Recusar cancelamento','iniciar'=>'Iniciar','finalizar'=>'Finalizar']as$a=>$l):?><button class="btn btn-outline" name="acao" value="<?= $a ?>" type="submit"><?= $l ?></button><?php endforeach;?></div></form></section>
<section class="panel-card"><div class="panel-card-heading"><h2>Hist&oacute;rico</h2></div><?php foreach($historico as$h):?><p><strong><?= e($fs($h['status_novo'])) ?></strong> &middot; <?= e(date('d/m/Y H:i',strtotime($h['criado_em']))) ?><?= $h['motivo']?' &middot; '.e($h['motivo']):'' ?></p><?php endforeach;?></section>
